export const concepts = [
  ['PYIN-R2-CON001', 'source file and interpreter', 'A .py file stores instructions; the selected Python interpreter reads and executes them.', '`py hello.py` runs the saved file with the Windows Python launcher.', 'Expecting a file to run merely because it is open in VS Code.'],
  ['PYIN-R2-CON002', 'edit-save-run cycle', 'Python executes the saved file, so an editor change must be saved before the next run.', 'Change a greeting, save, then repeat the same command.', 'Diagnosing old output before checking whether the file was saved.'],
  ['PYIN-R2-CON003', 'traceback evidence', 'A traceback names the failing file, line, exception type, and message.', 'NameError points to a name Python could not find.', 'Changing many lines before reading the last traceback entry.'],
  ['PYIN-R2-CON004', 'variable and value', 'A variable name refers to a value that may be used or replaced later.', '`hours = 6` binds the name hours to the integer 6.', 'Confusing the name with a quoted string containing that name.'],
  ['PYIN-R2-CON005', 'explicit conversion', 'Conversion deliberately produces a different type before an operation.', '`int("12")` produces the integer 12.', 'Adding numeric-looking text to a number.'],
  ['PYIN-R2-CON006', 'formatted string', 'An f-string inserts evaluated expressions into labelled text.', '`f"Total: {total}"` includes the current total.', 'Omitting the f prefix and printing braces literally.'],
  ['PYIN-R2-CON007', 'comparison chain', 'Comparisons and Boolean operators produce True or False for a decision.', '`16 <= age <= 120 and has_id`.', 'Using = when a comparison requires ==.'],
  ['PYIN-R2-CON008', 'ordered branch', 'if/elif/else checks conditions in order and takes the first matching branch.', 'Reject invalid data before eligibility rules.', 'Placing a broad success condition before a required rejection.'],
  ['PYIN-R2-CON009', 'narrow exception handling', 'A try block should contain only the operation whose expected failure is being handled.', 'Catch ValueError around int(age_text).', 'Catching Exception around the entire program and hiding defects.'],
  ['PYIN-R2-CON010', 'while-loop progress', 'A while loop must have a condition and an action that can move it toward stopping.', 'Increment attempts after each failed guess.', 'Forgetting the update and creating an infinite loop.'],
  ['PYIN-R2-CON011', 'list index and length', 'List indexes begin at zero while len counts stored values.', '`scores[-1]` reads the last score.', 'Reading scores[len(scores)] as the last item.'],
  ['PYIN-R2-CON012', 'for-loop traversal', 'A for loop visits each item in an iterable without manual index arithmetic.', '`for score in scores:` processes every stored score.', 'Changing list length unexpectedly while traversing it.'],
  ['PYIN-R2-CON013', 'dictionary record', 'A dictionary groups values under meaningful keys.', '`student["name"]` reads the name field.', 'Using a positional index for a named field.'],
  ['PYIN-R2-CON014', 'function contract', 'A focused function accepts stated inputs and returns or performs one understandable result.', '`calculate_total(prices)` returns one number.', 'Making one function collect input, calculate, save, and print everything.'],
  ['PYIN-R2-CON015', 'return value', 'return sends a value to the caller and ends that call.', '`return subtotal - discount` lets another function format the result.', 'Printing a value when the caller needs to use it.'],
  ['PYIN-R2-CON016', 'local scope', 'A name created inside a function is local unless deliberately passed or returned.', 'subtotal is local to calculate_total.', 'Reading a local name from outside the function.'],
  ['PYIN-R2-CON017', 'path object', 'A Path represents a filesystem location and can be joined without fragile string separators.', '`Path(__file__).parent / "data" / "expenses.json"`.', 'Assuming the terminal always starts in the project folder.'],
  ['PYIN-R2-CON018', 'with block', 'A with block closes an opened file even when an operation fails.', '`with path.open("r", encoding="utf-8") as handle:`.', 'Leaving files open or relying on a platform-default encoding.'],
  ['PYIN-R2-CON019', 'JSON round trip', 'json.dump/load or dumps/loads convert supported Python data to JSON and back.', 'A list of expense dictionaries can be saved and loaded.', 'Expecting JSON to restore class methods or arbitrary Python types.'],
  ['PYIN-R2-CON020', 'class and instance', 'A class describes construction and behavior; each instance carries its own attributes.', '`Book("Kindred")` creates one Book instance.', 'Using a class attribute when each object needs separate state.'],
  ['PYIN-R2-CON021', 'self', 'self refers to the instance receiving a method call.', '`self.available = False` changes that instance.', 'Omitting self from an instance method definition.'],
  ['PYIN-R2-CON022', 'method invariant', 'A method can reject an invalid state transition before changing the object.', 'checkout rejects a book that is already borrowed.', 'Changing state first and validating afterward.'],
  ['PYIN-R2-CON023', 'module import', 'A module exposes reusable names while application flow stays in an entry file.', '`from flashcards import choose_card`.', 'Creating circular imports or running the CLI during import.'],
  ['PYIN-R2-CON024', 'main guard', 'The __name__ guard runs application code only when its file is the entry point.', '`if __name__ == "__main__": main()`.', 'Putting tests or user prompts at module top level.'],
  ['PYIN-R2-CON025', 'test assertion', 'An assertion compares actual behavior with an expected result and reports a mismatch.', '`self.assertEqual(total, 2500)`.', 'Changing the expected result only to make a test pass.'],
  ['PYIN-R2-CON026', 'debugger breakpoint', 'A breakpoint pauses before a suspicious line so local values and control flow can be inspected.', 'Pause before a return and inspect the calculated result.', 'Adding many prints before reducing the failure to one case.'],
  ['PYIN-R2-CON027', 'argparse contract', 'argparse turns declared command-line choices into validated values and generated help.', '`parser.add_argument("--status", choices=["open", "done"])`.', 'Splitting raw command text by hand and accepting ambiguous input.'],
  ['PYIN-R2-CON028', 'reproducible repository', 'A repository is reviewable when its tracked files and README let another person run and test it safely.', 'README gives exact Python and unittest commands.', 'Publishing credentials, private data, caches, or undocumented commands.'],
].map(([id, term, simpleMeaning, example, commonMistake]) => ({ id, term, simpleMeaning, example, commonMistake }));

const build = ({ week, title, outcome, brief, competencyIds, priorKnowledgeCompetencyIds, conceptRefs, whyItMatters, steps, criteria, hints, templates, stretch, sessions, finishedResult }) => {
  const prefix = `PYIN-R2-B-W${String(week).padStart(2, '0')}-01`;
  return {
    id: prefix,
    title,
    required: true,
    outcome,
    competencyIds,
    estimatedMinutes: sessions.reduce((sum, session) => sum + session.minutes, 0),
    brief,
    steps: steps.map((text, index) => ({ id: `${prefix}-S${String(index + 1).padStart(2, '0')}`, text })),
    acceptanceCriteria: criteria.map((text, index) => ({ id: `${prefix}-A${String(index + 1).padStart(2, '0')}`, text })),
    hints,
    templates: templates.map((item, index) => ({ id: `${prefix}-T${String(index + 1).padStart(2, '0')}`, ...item })),
    stretch,
    learnerGuide: {
      summary: brief,
      whyItMatters,
      priorKnowledgeCompetencyIds,
      finishedResult,
      conceptRefs,
      sessions: sessions.map((session, index) => ({
        id: `${prefix}-SESSION-${String(index + 1).padStart(2, '0')}`,
        title: session.title,
        estimatedMinutes: session.minutes,
        stepIds: session.stepIndexes.map((stepIndex) => `${prefix}-S${String(stepIndex).padStart(2, '0')}`),
      })),
    },
  };
};

